<?php
$item = $data['item']; $staff = $data['staff']; $status = $item['status'];
$root = $staff ? '/dashboard/admin/training/requests' : '/dashboard/school/training';
$values = $data['values']; $value = static fn (string $key): string => (string) ($values[$key] ?? '');
$active = !in_array($status, ['completed', 'cancelled'], true);
$assignedActive = in_array((int) ($item['assigned_admin_id'] ?? 0), array_map(static fn (array $admin): int => (int) $admin['id'], $data['admins']), true);
$approved = !empty($item['approved_by']);
$hidden = static function (string $action) use ($escape, $data, $item): void { ?>
<input type="hidden" name="_csrf" value="<?= $escape($data['csrf']) ?>"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $item['revision'] ?>"><input type="hidden" name="action" value="<?= $escape($action) ?>">
<?php };
$sessionValue = static function (string $input, string $stored) use ($values, $item): string {
    if (array_key_exists($input, $values)) { return (string) $values[$input]; }
    return empty($item[$stored]) ? '' : (new DateTimeImmutable($item[$stored], new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Africa/Lagos'))->format('Y-m-d\TH:i');
};
?>
<section class="page-band"><div class="site-shell"><a href="<?= $root ?>">Back to training requests</a><h1 class="mt-3"><?= $escape($data['title']) ?></h1><p><span class="status-badge"><?= $escape(ucfirst(str_replace('_', ' ', $status))) ?></span> · Revision <?= (int) $item['revision'] ?></p><?php if ($staff): ?><p><?= $escape($item['school_name']) ?></p><?php endif; ?></div></section>
<div class="site-shell section-space">
<?php if ($data['notice'] !== ''): ?><p class="auth-notice" role="status"><?= $escape($data['notice']) ?></p><?php endif; ?>
<?php if ($data['error'] !== ''): ?><div class="alert alert-danger" role="alert"><?= $escape($data['error']) ?></div><?php endif; ?>
<div class="row g-4"><div class="<?= $staff && $active ? 'col-lg-8' : 'col-12' ?>">
<section class="form-panel mb-4"><h2 class="h4">School requirements</h2><dl class="row"><dt class="col-sm-4">Participants</dt><dd class="col-sm-8"><?= (int) $item['participants'] ?></dd><dt class="col-sm-4">Location</dt><dd class="col-sm-8"><?= $escape($item['location']) ?></dd><dt class="col-sm-4">Preferred dates (WAT)</dt><dd class="col-sm-8" style="white-space:pre-line"><?= $escape(is_array($item['preferred_dates']) ? implode("\n", $item['preferred_dates']) : $item['preferred_dates']) ?></dd><dt class="col-sm-4">Requirements</dt><dd class="col-sm-8" style="white-space:pre-line"><?= $escape($item['requirements'] ?: 'None supplied') ?></dd><dt class="col-sm-4">Submitted</dt><dd class="col-sm-8"><?= $escape($data['wat']($item['created_at'])) ?> WAT</dd></dl>
<?php $messageUrl = $staff ? '/dashboard/admin/messages?' . http_build_query(['new' => 1, 'owner_id' => $item['school_id'], 'owner_role' => 'school', 'context_type' => 'training', 'context_id' => $item['id']]) : '/messages?' . http_build_query(['new' => 1, 'context_type' => 'training', 'context_id' => $item['id']]); ?>
<a class="btn button button-outline" href="<?= $escape($messageUrl) ?>"><?= $staff ? 'Message school about this request' : 'Message management about this request' ?></a></section>
<section class="form-panel mb-4"><h2 class="h4">Submitted training details</h2><p>These details reflect the training selected when this request was submitted.</p><?php if (!empty($item['package_title'])): ?><h3 class="h5">Package: <?= $escape($item['package_title']) ?></h3><?php endif; ?>
<?php foreach ($item['modules'] as $snapshot): $module = $snapshot['snapshot']; ?><details class="border-top py-3"><summary class="fw-semibold"><?= $escape($snapshot['title_snapshot']) ?></summary><p class="mt-3" style="white-space:pre-line"><?= $escape((string) ($module['description'] ?? '')) ?></p><?php require __DIR__ . '/module-fields.php'; ?></details><?php endforeach; ?></section>
<?php if (!empty($item['scheduled_start'])): ?><section class="form-panel mb-4"><h2 class="h4"><?= $status === 'cancelled' ? 'Previous session schedule' : 'Session schedule' ?></h2><p><?= $escape($data['wat']($item['scheduled_start'])) ?> – <?= $escape($data['wat']($item['scheduled_end'])) ?> WAT</p><p><?= $escape(ucfirst(str_replace('_', '-', $item['session_format']))) ?> · <?= $escape($item['session_location']) ?></p></section><?php endif; ?>
<?php if (!empty($item['outcome'])): ?><section class="form-panel mb-4"><h2 class="h4">Session outcome</h2><p style="white-space:pre-line"><?= $escape($item['outcome']) ?></p></section><?php endif; ?>
<section class="form-panel"><h2 class="h4">Request history</h2><?php if (empty($item['history'])): ?><p data-empty-state>No decisions have been recorded yet.</p><?php endif; ?><ol class="list-group list-group-flush"><?php foreach ($item['history'] as $entry): ?><li class="list-group-item px-0"><strong><?= $escape(ucfirst(str_replace('_', ' ', $entry['action']))) ?></strong><p class="small mb-1"><?= $escape($data['wat']($entry['created_at'])) ?> WAT<?= $staff ? ' · Account #' . (int) $entry['actor_id'] : '' ?></p><?php if (!empty($entry['note'])): ?><p class="mb-1" style="white-space:pre-line"><?= $escape($entry['note']) ?></p><?php endif; ?><?php if (!empty($entry['to_status'])): ?><p class="small mb-0">Status: <?= $escape(ucfirst(str_replace('_', ' ', $entry['to_status']))) ?></p><?php endif; ?></li><?php endforeach; ?></ol></section>
<?php if (!$active): ?><p class="mt-4">This request is <?= $escape($status) ?> and its decisions can no longer be changed.</p><?php endif; ?>
</div>
<?php if ($staff && $active): ?><aside class="col-lg-4">
<p class="small">Decision notes and outcomes are shared with the requesting school.</p>
<section class="form-panel mb-4"><h2 class="h4">Assigned staff</h2><p><?= $approved ? 'Approval has been recorded.' : 'No approval is currently recorded.' ?></p><?php if (!$assignedActive && !empty($item['assigned_admin_id'])): ?><p class="text-danger">The assigned staff account is no longer active. Assign an active administrator before approval or scheduling.</p><?php endif; ?>
<?php if ($status !== 'scheduled'): ?><form class="auth-form" method="post" action="<?= $root ?>"><?php $hidden('assign'); ?><div><label class="form-label" for="training-assignee">Active administrator</label><select class="form-select" id="training-assignee" name="assigned_admin_id" required><option value="">Choose staff</option><?php foreach ($data['admins'] as $admin): ?><option value="<?= (int) $admin['id'] ?>"<?= (string) ($values['assigned_admin_id'] ?? $item['assigned_admin_id']) === (string) $admin['id'] ? ' selected' : '' ?>><?= $escape($admin['email']) ?></option><?php endforeach; ?></select></div><p class="small">Reassignment clears approval. Assignment changes are unavailable while scheduled.</p><button class="btn button button-outline" type="submit"<?= $data['admins'] === [] ? ' disabled' : '' ?>>Assign staff</button></form><?php else: ?><p>Account #<?= (int) $item['assigned_admin_id'] ?></p><?php endif; ?></section>
<?php if (in_array($status, ['submitted', 'under_review'], true)): $action = $status === 'submitted' ? 'under_review' : 'discussion'; ?><section class="form-panel mb-4"><h2 class="h4"><?= $status === 'submitted' ? 'Start review' : 'Discuss requirements' ?></h2><form class="auth-form" method="post" action="<?= $root ?>"><?php $hidden($action); ?><div><label class="form-label" for="training-progress-note">Decision note</label><textarea class="form-control" id="training-progress-note" name="note" rows="3" maxlength="4000" required><?= $escape($value('note')) ?></textarea></div><button class="btn button button-primary" type="submit"><?= $status === 'submitted' ? 'Mark under review' : 'Move to discussion' ?></button></form></section><?php endif; ?>
<?php if ($status === 'discussion' && !$approved): ?><section class="form-panel mb-4"><h2 class="h4">Approve training</h2><p>Approval records a decision while the request remains in discussion. An active staff assignee is required before scheduling.</p><?php if ($assignedActive): ?><form class="auth-form" method="post" action="<?= $root ?>"><?php $hidden('approve'); ?><div><label class="form-label" for="training-approval-note">Approval note</label><textarea class="form-control" id="training-approval-note" name="note" rows="3" maxlength="4000" required><?= $escape($value('note')) ?></textarea></div><button class="btn button button-primary" type="submit">Record approval</button></form><?php else: ?><p>Assign an active administrator first.</p><?php endif; ?></section><?php endif; ?>
<?php if ($assignedActive && $approved && in_array($status, ['discussion', 'scheduled'], true)): $reschedule = $status === 'scheduled'; ?><section class="form-panel mb-4"><h2 class="h4"><?= $reschedule ? 'Reschedule session' : 'Schedule approved training' ?></h2><p>Session times use West Africa Time (Africa/Lagos). Scheduling rechecks school approval and staff eligibility.</p><form class="auth-form" method="post" action="<?= $root ?>"><?php $hidden($reschedule ? 'reschedule' : 'schedule'); ?>
<?php foreach (['starts_at' => ['Start time (WAT)', 'scheduled_start'], 'ends_at' => ['End time (WAT)', 'scheduled_end']] as $key => [$label, $stored]): ?><div><label class="form-label" for="training-<?= $key ?>"><?= $label ?></label><input class="form-control" id="training-<?= $key ?>" type="datetime-local" name="<?= $key ?>" value="<?= $escape($sessionValue($key, $stored)) ?>" required></div><?php endforeach; ?>
<div><label class="form-label" for="training-session-format">Delivery format</label><select class="form-select" id="training-session-format" name="delivery_format" required><?php foreach (['on_site' => 'On-site', 'online' => 'Online', 'hybrid' => 'Hybrid'] as $key => $label): ?><option value="<?= $key ?>"<?= ($values['delivery_format'] ?? $item['session_format'] ?? '') === $key ? ' selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div>
<div><label class="form-label" for="training-session-location">Session location / online arrangements</label><input class="form-control" id="training-session-location" name="session_location" maxlength="500" value="<?= $escape((string) ($values['session_location'] ?? $item['session_location'] ?? '')) ?>" required></div><div><label class="form-label" for="training-schedule-note"><?= $reschedule ? 'Reason for rescheduling' : 'Scheduling note' ?></label><textarea class="form-control" id="training-schedule-note" name="note" rows="3" maxlength="4000" required><?= $escape($value('note')) ?></textarea></div><button class="btn button button-primary" type="submit"><?= $reschedule ? 'Reschedule session' : 'Confirm schedule' ?></button></form></section><?php endif; ?>
<?php if ($status === 'scheduled'): ?><section class="form-panel mb-4"><h2 class="h4">Complete training</h2><?php if (!empty($item['scheduled_end']) && new DateTimeImmutable($item['scheduled_end'], new DateTimeZone('UTC')) <= new DateTimeImmutable('now', new DateTimeZone('UTC'))): ?><form class="auth-form" method="post" action="<?= $root ?>"><?php $hidden('complete'); ?><div><label class="form-label" for="training-outcome">Session outcome (required)</label><textarea class="form-control" id="training-outcome" name="outcome" rows="4" maxlength="4000" required><?= $escape($value('outcome')) ?></textarea></div><button class="btn button button-primary" type="submit">Mark completed</button></form><?php else: ?><p>Completion becomes available after the scheduled session ends.</p><?php endif; ?></section><?php endif; ?>
<section class="form-panel"><h2 class="h4">Cancel request</h2><p>Cancellation closes the request and cannot be reversed.</p><form class="auth-form" method="post" action="<?= $root ?>"><?php $hidden('cancel'); ?><div><label class="form-label" for="training-cancel-note">Cancellation reason (required)</label><textarea class="form-control" id="training-cancel-note" name="note" rows="3" maxlength="4000" required><?= $escape($value('note')) ?></textarea></div><button class="btn button button-outline" type="submit">Cancel training request</button></form></section>
</aside><?php endif; ?></div></div>
